WITH with_latest AS (SELECT s.*, latest.transaction_txn_time, latest.amount FROM accounts s JOIN LATERAL (SELECT c.txn_time AS transaction_txn_time, c.amount FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT status, CASE WHEN amount >= 4000 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, SUM(balance) AS total_balance, SUM(CASE WHEN status = 'FROZEN' THEN balance ELSE 0 END) AS frozen_balance, MAX(amount) AS max_amount, COUNT_IF(account_type = 'LOAN') AS loan_events, ROUND(AVG(balance), 2) AS avg_balance FROM with_latest GROUP BY GROUPING SETS ((status, CASE WHEN amount >= 4000 THEN 'LARGE' ELSE 'SMALL' END), (status)) ORDER BY avg_balance NULLS FIRST;
